package com.narudzbine.identity.infrastructure.web;

import com.narudzbine.pricing.api.*;
import com.narudzbine.trading.api.TradingConnections;
import com.narudzbine.identity.api.*;
import com.narudzbine.identity.application.*;
import com.narudzbine.organizations.api.*;
import com.narudzbine.shared.api.ResourceRevisions;
import jakarta.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.math.BigDecimal;
import java.util.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.http.ResponseEntity;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/relationships/{relationshipId}/agreed-prices")
@ConditionalOnProperty(name="identity.http.enabled",havingValue="true")
public final class AgreedPriceController {
 private final SessionService sessions;private final MembershipAccess memberships;private final BusinessAuthorization authorization;private final AgreedPrices prices;private final TradingConnections trading;private final SessionTransportPolicy policy;private final LoginThrottle throttle;private final ResourceRevisions revisions;private final TransactionTemplate tx;
 AgreedPriceController(SessionService sessions,MembershipAccess memberships,BusinessAuthorization authorization,AgreedPrices prices,TradingConnections trading,SessionTransportPolicy policy,LoginThrottle throttle,ResourceRevisions revisions,PlatformTransactionManager manager){this.sessions=sessions;this.memberships=memberships;this.authorization=authorization;this.prices=prices;this.trading=trading;this.policy=policy;this.throttle=throttle;this.revisions=revisions;tx=new TransactionTemplate(manager);tx.setTimeout(10);}
 @GetMapping Page list(@PathVariable String relationshipId,HttpServletRequest request){AuthController.noBody(request);var query=AgreedPriceRequests.query(request);UUID id=ContactRequests.id(relationshipId,"PATH","relationshipId");var selected=policy.select(request);var initial=admit(selected,id,false);return tx.execute(status->{var scope=scope(selected,initial,null,false);var r=trading.get(scope.organizationId(),id);var page=prices.list(scope.organizationId(),id,query.page(),query.size(),query.total());activity(selected);return new Page(page.items().stream().map(this::response).toList(),query.page(),query.size(),page.total(),revisions.encode("agreedpricing/v1",id,page.pricingRevision()),revisions.encode("relationship/v1",id,r.revision()));});}
 @PutMapping("/{productId}") Result set(@PathVariable String relationshipId,@PathVariable String productId,HttpServletRequest request)throws IOException{AuthController.noQuery(request);UUID id=ContactRequests.id(relationshipId,"PATH","relationshipId"),product=ContactRequests.id(productId,"PATH","productId");var input=AgreedPriceRequests.input(request);var selected=policy.select(request);String csrf=csrf(selected,request);var initial=admit(selected,id,true);return tx.execute(status->{var scope=scope(selected,initial,csrf,true);var old=prices.find(scope.organizationId(),id,product);if(old.isPresent()){requirePriceRevision(old.get(),input.revision());}else if(input.revision()!=null){throw new AgreedPriceFailure(AgreedPriceFailure.Reason.REVISION_CONFLICT);}var result=prices.set(scope.accountId(),scope.organizationId(),id,product,old.map(AgreedPrices.Item::revision).orElse(null),input.price());activity(selected);return response(result);});}
 @DeleteMapping("/{productId}") ResponseEntity<Void> remove(@PathVariable String relationshipId,@PathVariable String productId,HttpServletRequest request){AuthController.noBody(request);String expected=TaxonomyRequests.deletion(request);UUID id=ContactRequests.id(relationshipId,"PATH","relationshipId"),product=ContactRequests.id(productId,"PATH","productId");var selected=policy.select(request);String csrf=csrf(selected,request);var initial=admit(selected,id,true);return tx.execute(status->{var scope=scope(selected,initial,csrf,true);var old=prices.find(scope.organizationId(),id,product).orElseThrow(()->new AgreedPriceFailure(AgreedPriceFailure.Reason.NOT_FOUND));requirePriceRevision(old,expected);prices.remove(scope.accountId(),scope.organizationId(),id,product,old.revision());activity(selected);return ResponseEntity.noContent().build();});}
 @PostMapping("/confirmation") TradingController.Relationship confirm(@PathVariable String relationshipId,HttpServletRequest request)throws IOException{AuthController.noQuery(request);UUID id=ContactRequests.id(relationshipId,"PATH","relationshipId");var input=AgreedPriceRequests.confirmation(request);var selected=policy.select(request);String csrf=csrf(selected,request);var initial=admit(selected,id,true);return tx.execute(status->{var scope=scope(selected,initial,csrf,true);var r=trading.get(scope.organizationId(),id);long priceRevision=prices.list(scope.organizationId(),id,0,1,false).pricingRevision();requireRevision("relationship/v1",id,r.revision(),input.relationshipRevision());requireRevision("agreedpricing/v1",id,priceRevision,input.pricingRevision());prices.confirm(scope.accountId(),scope.organizationId(),id,r.revision(),priceRevision,input.products());var result=trading.get(scope.organizationId(),id);activity(selected);return new TradingController.Relationship(result.id(),revisions.encode("relationship/v1",id,result.revision()),result.vendorId(),result.buyerId(),result.country(),result.state(),result.disconnectedReason(),result.confirmationRequired(),AccountResponses.time(result.createdAt()),AccountResponses.time(result.updatedAt()));});}
 private TradingConnections.View admit(SessionTransportPolicy.Selected selected,UUID relationship,boolean write){UUID actor=tx.execute(s->sessions.authenticate(selected.secret(),selected.transport()).accountId());throttle.admitApi(actor,write);return tx.execute(s->{var member=memberships.lockForAuthorization(actor).orElseThrow(()->new BusinessAccessDenied(BusinessAccessDenied.Reason.INACCESSIBLE_SCOPE));sessions.authenticate(selected.secret(),selected.transport());if(member.type()!=OrganizationType.VENDOR){throw new BusinessAccessDenied(BusinessAccessDenied.Reason.INACCESSIBLE_SCOPE);}authorization.require(actor,member.organizationId(),member.country(),BusinessCapability.EDIT_PRICES);return trading.get(member.organizationId(),relationship);});}
 private BusinessScope scope(SessionTransportPolicy.Selected selected,TradingConnections.View initial,String csrf,boolean write){var principal=sessions.authenticateForTradingWrite(selected.secret(),selected.transport(),initial.vendorId(),initial.buyerId(),null);if(write&&selected.transport()==SessionTransport.BROWSER){sessions.requireCsrf(selected.secret(),csrf);}var member=memberships.lockForAuthorization(principal.accountId()).orElseThrow(()->new BusinessAccessDenied(BusinessAccessDenied.Reason.INACCESSIBLE_SCOPE));if(member.type()!=OrganizationType.VENDOR||!member.organizationId().equals(initial.vendorId())){throw new BusinessAccessDenied(BusinessAccessDenied.Reason.INACCESSIBLE_SCOPE);}return authorization.require(principal.accountId(),member.organizationId(),member.country(),BusinessCapability.EDIT_PRICES);}
 private void requirePriceRevision(AgreedPrices.Item item,String expected){requireRevision("agreedprice/v1",item.id(),item.revision(),expected);}
 private void requireRevision(String domain,UUID id,long current,String expected){if(expected==null||!revisions.matches(domain,id,current,expected)){throw new RevisionConflict(revisions.encode(domain,id,current));}}
 private static String csrf(SessionTransportPolicy.Selected selected,HttpServletRequest request){return selected.transport()==SessionTransport.BROWSER?AuthController.csrfHeader(request):null;}
 private void activity(SessionTransportPolicy.Selected selected){sessions.recordSuccessfulActivity(selected.secret(),selected.transport());}
 private Result response(AgreedPrices.Item i){return new Result(i.id(),revisions.encode("agreedprice/v1",i.id(),i.revision()),i.productId(),i.buyerOrganizationId(),i.unitPrice().toPlainString(),i.confirmationRequired());}
 record Result(UUID id,String revision,UUID productId,UUID buyerOrganizationId,String unitPrice,boolean confirmationRequired){}
 record Page(List<Result> items,int page,int size,Long total,String pricingRevision,String relationshipRevision){}
}
